const materialData = [ { id: 'mat-coton', name: "Coton" }, { id: 'mat-laine', name: "Laine" }, { id: 'mat-soie', name: "Soie" }, ]
await prisma.category.createMany({ data: categoryData }) await prisma.size.createMany({ data: sizeData }) await prisma.color.createMany({ data: colorData }) await prisma.material.createMany({ data: materialData })
const password = await bcrypt.hash("wovelypass", 10)
const clientInfos = [ ["Alice", "Durand", "alice.durand@wovely.com", "alice"], ["Camille", "Petit", "camille.petit@wovely.com", "camille"], ["Léa", "Bernard", "lea.bernard@wovely.com", "lea"], ["Nina", "Giraud", "nina.giraud@wovely.com", "nina"], ["Sophie", "Lemoine", "sophie.lemoine@wovely.com", "sophie"], ["Emma", "Roux", "emma.roux@wovely.com", "emma"], ["Julie", "Fabre", "julie.fabre@wovely.com", "julie"], ["Clara", "Noel", "clara.noel@wovely.com", "clara"], ["Chloé", "Marchand", "chloe.marchand@wovely.com", "chloe"], ["Eva", "Pires", "eva.pires@wovely.com", "eva"] ]
const clients = [] for (let i = 0; i < clientInfos.length; i++) { const [firstname, lastname, email, username] = clientInfos[i] const user = await prisma.user.create({ data: { email, username, password, role: Role.CLIENT }, }) const client = await prisma.client.create({ data: { firstname, lastname, phoneNumber: `060000000${i + 1}`, userId: user.id, agreeTerms: true, receiveAlerts: i % 2 === 0, }, }) clients.push(client) }
